&lt;h2&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;COMPENSATION&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The ACLU has a litigator scale that&amp;nbsp;determines&amp;nbsp;pay for attorneys in our Legal Department. The range of salaries are the following, based on&amp;nbsp;year&amp;nbsp;of law school graduation (please consult the hiring manager for specific salary details, based on individual circumstances).&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;0-2 years since law school graduation: $96,069 - $120,009&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;3-5 years since law school graduation: $134,414 - $158,579&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;6-10 years since law school graduation: $165,839 - $187,087&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;11-15 years since law school graduation: $190,585 - $201,403&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;16-20 years since law school graduation: $203,304 - $208,540&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;21-25 years since law school graduation: $209,595 - $213,890&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;26-30+ years since law school graduation: $214,920 - $219,104&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The ACLU is committed to equity, transparency, and clarity in pay. These salaries are reflective of positions based in New York,&amp;nbsp;NY,&amp;nbsp;where&amp;nbsp;our&amp;nbsp;National Offices are headquartered.&amp;nbsp;&amp;nbsp;Salaries are subject to a regional pay adjustment if authorization is granted to work outside of the location listed in this&amp;nbsp;posting.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For details on our pay structure, please visit:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.aclu.org/careers/ACLU_Geographic_Pay_Structure-July_2024.pdf&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.aclu.org/careers/ACLU_Geographic_Pay_Structure-July_2024.pdf&lt;/span&gt;&lt;/span&gt;&lt;/a&gt; &lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;WHY THE ACLU&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For over 100 years, the ACLU has worked to defend and preserve the individual rights and liberties guaranteed by the Constitution and laws of the United States. Whether&amp;nbsp;it’s&amp;nbsp;ending mass incarceration, achieving full equality for the LGBTQ+ community,&amp;nbsp;establishing&amp;nbsp;new privacy protections for our digital age, or preserving the right to vote or the right to have an abortion, the ACLU takes up the toughest civil liberties cases and issues to defend all people.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We know that great people make a great organization. We value our people and know that what we offer is essential not&amp;nbsp;just&amp;nbsp;their work, but to their overall well-being.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the ACLU, we offer a broad range of benefits, which include:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Time away to focus on the things that matter with a generous paid time-off policy&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Focus on your well-being with comprehensive healthcare benefits (including medical, dental and vision coverage, parental leave, gender affirming care &amp;amp; fertility treatment)&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Plan for your retirement with 401k plan and employer match&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We support employee growth and development through annual professional development funds, internal professional development programs and workshops&lt;/span&gt; &amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;OUR COMMITMENT TO ACCESSIBILITY, EQUITY, DIVERSITY &amp;amp; INCLUSION&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Accessibility, equity, diversity and inclusion are core values of the ACLU and central to our work to advance liberty, equality, and justice for all. For us diversity, equity, accessibility, and inclusion are not just check-the-box activities, but a chance for us to make long-term meaningful change.&amp;nbsp; We are a community committed to learning and growth, humility and grace, transparency and accountability. We believe in a collective responsibility to create a culture of belonging for all people within our organization – one that respects and embraces difference; treats everyone equitably; and empowers our colleagues to do the best work possible. We are as committed to anti-oppression, anti-ableism, and anti-racism internally as we are externally. Because whether we’re in the courts or in the office, we believe ‘We the People’ means all of us.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;With this commitment in mind, we strongly encourage applications from all qualified individuals without regard to race, color, religion, gender, sexual orientation, gender identity or expression, age, national origin, marital status, citizenship, disability, veteran status and record of arrest or conviction, or any other characteristic protected by applicable law.&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The ACLU is committed to providing reasonable accommodation to individuals with disabilities. If you are a qualified individual with a disability and need&amp;nbsp;assistance&amp;nbsp;applying online, please email&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;a href=&quot;mailto:benefits.hrdept@aclu.org&quot;&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;benefits.hrdept@aclu.org&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;/a&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;. If you are selected for an interview, you will receive&amp;nbsp;additional&amp;nbsp;information&amp;nbsp;regarding&amp;nbsp;how to request&amp;nbsp;an accommodation&amp;nbsp;for the interview process.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;

leadershipforeducationalequity-khan-acad.descriptionHtml:
&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ABOUT KHAN ACADEMY&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Khan Academy is a fast-paced nonprofit on a mission to provide free, world-class education for anyone, anywhere. We reach millions of students every month and are growing rapidly. We’re building a library of world-class instructional and practice resources that empowers learners. Whether they’re studying matrices, mitosis, or multivariable calculus, we want to offer students the resources to realize that they can learn anything.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ABOUT KHAN ACADEMY INDIA&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Khan Academy India aims to deliver a world-class user experience to learners in India that is locally relevant and are enabled by a strong on-the-ground team and operations. Our learning system is mastery-based, which allows students to master key concepts at a pace that’s right for them before moving on to more challenging content. From serving under 500,000 learners in 2016, we are now serving almost 4 million learners a month across our websites, apps, and YouTube channels. These learners include both independent learners accessing us at home, and teacher-directed learners in schools.&amp;nbsp; Our focus is to reach the underserved by making our content accessible in local languages and by working with &lt;strong&gt;large public school systems&lt;/strong&gt;. Khan Academy is already available in Assamese, Hindi, Hinglish, Kannada, Gujarati, Tamil, Marathi, and Punjabi.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ABOUT THE INDIA CONTENT&amp;nbsp; TEAM&lt;/strong&gt;&lt;br&gt;Our content team in India includes content creators who make thousands of awesome videos, articles, and practice questions aligned with the Indian curriculum to help both teachers and students. We are actively working on content localization in other regional languages as well, which means the content we co-create reaches a wider number (both nationally and globally), thereby quintupling the impact.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ABOUT THE ROLE&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are looking for a Math subject matter expert to &lt;strong&gt;lead&lt;/strong&gt; our efforts of creating syllabus-aligned videos, practice questions and conduct quality checks primarily aligned for Grades 6-12. This will be a &lt;strong&gt;contract position&lt;/strong&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;Note: This role is open to citizens living in India Only.&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;In this role, you would:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Manage a team of freelancers.&lt;/li&gt;
&lt;li&gt;Onboard freelancers on Khan Academy content principles.&lt;/li&gt;
&lt;li&gt;Conduct quality checks for exercises and videos in Math Grades 6-12.&lt;/li&gt;
&lt;li&gt;Create videos and exercises for Math Grades 6-12.&lt;/li&gt;
&lt;li&gt;Continuously iterate and improve content based on feedback received.&lt;/li&gt;
&lt;li&gt;Curate courses and lead workshops to collect feedback on the content.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;ABOUT YOU:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You would be a great fit for the role if&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You have a combined 4+ years of experience in teaching and creating educational content for Math. Impeccable written communication skills are must haves.&lt;em&gt;&amp;nbsp;&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;You have the ability to timebox effortlessly. Our greatest strength is the ability to pace up whenever needed by timeboxing on content. This requires us to have the ‘shipping beats perfection’ mindset.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You don’t need to be managed: We lead with context, not control. We expect you to be proactive and ask clarifying questions, provide status updates, loop in your manager when things aren&#39;t going your way, etc.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You have an entrepreneurial mindset, including a high tolerance for ambiguity, a penchant for experimentation, and a bias toward action. You are willing to roll up your sleeves and help the team get work done as we grow.&lt;/li&gt;
&lt;li&gt;You are passionate about education and strongly desire to change the world for the better.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;PERKS AND BENEFITS&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We may be a non-profit, but we reward our talented team like a for-profit.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Remote-friendly workplace; Flexible schedules&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Fun virtual events&lt;/li&gt;
&lt;li&gt;Competitive salaries&lt;/li&gt;
&lt;li&gt;Professional development focus&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;LEARN MORE&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;http://www.ted.com/talks/salman_khan_let_s_use_video_to_reinvent_education&quot;&gt;Sal’s TED talk from 2011&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;http://www.ted.com/talks/sal_khan_let_s_teach_for_mastery_not_test_scores&quot;&gt;Sal’s TED talk from 2015&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;A glimpse of our team:&amp;nbsp; &lt;a href=&quot;http://www.khanacademy.org/about/the-team&quot;&gt;http://www.khanacademy.org/about/the-team&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;A glimpse of our content created: &lt;a href=&quot;https://www.youtube.com/watch?v=ED8P8vchQJM&quot;&gt;https://www.youtube.com/watch?v=ED8P8vchQJM&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Our Hinglish content in action: &lt;a href=&quot;http://bit.ly/khanacademyyoutube&quot;&gt;http://bit.ly/khanacademyyoutube&lt;/a&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;HOW TO APPLY&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Attach your resume or LinkedIn URL in the space provided below.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Please address the below-mentioned task and attach your response in the space provided below.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Please note that applications without an appropriate link to the task will be ignored.&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Please address the below-mentioned task and attach your response (google Docs/pdf/etc.) in the space provided below. (For the videos, upload them on google drive/YouTube and share the link in the doc)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Link to the task: &lt;a href=&quot;https://docs.google.com/document/d/16AMDFY4f-zT0ssC0igGXHQ2WkdjkbANyyfd1Y-PcVbE/edit?tab=t.0&quot;&gt;&lt;strong&gt;Task - Math SME [External]&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are committed to equal employment opportunities regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital status, disability, or veteran status.&lt;/em&gt;&lt;/p&gt;

leadershipforeducationalequity-teach-for.descriptionHtml:
&lt;h4&gt;&lt;strong&gt;Position Summary&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;To advance&amp;nbsp; &lt;a href=&quot;https://teachforall.org/our-purpose&quot;&gt;Teach For All’s 25-year vision&lt;/a&gt;, we are seeking a strategic AI leader developer to join our Technology &amp;amp; Innovation team and work globally to identify and implement transformative technology solutions to accelerate the impact of our global network.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This role will &lt;strong&gt;work across the network with partners or groups of partners in order to identify and deliver transformative AI-forward&amp;nbsp; technology products to accelerate network impact&lt;/strong&gt;, as well as &lt;strong&gt;internally across the global organization to increase efficiency and effectiveness of our work&lt;/strong&gt;.&amp;nbsp; The successful candidate will also be responsible for &lt;strong&gt;helping build and cultivate a community of technology enthusiasts across the network made up of network staff members, fellows and alumni&lt;/strong&gt; who will contribute to these projects.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;About the Team&amp;nbsp;&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;The Technology &amp;amp; Innovation Team provides &lt;strong&gt;thought-leadership and solutions&lt;/strong&gt; as well as &lt;strong&gt;foundational support&lt;/strong&gt; in the use of technology to unlock potential and accelerate impact &lt;strong&gt;across the organization and the global network&lt;/strong&gt;. The team leverages a deep understanding of the work and needs of the global organization, its teams and partners, our own expertise and global best practice to provide targeted solutions and technologies to accelerate our global impact. You will play a key role in this work.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;Outcomes&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Identifying and delivering key AI-forward technologies for network partners&lt;/strong&gt; to support their work.&amp;nbsp; These may include tools for common needs across the network – classroom data collection, professional development of fellows, scheduling and management of Assessment Centers (where teaching fellows are selected) or new platforms (connectivity tools, online learning) -&amp;nbsp; which are identified and scoped in partnership with our network partners. Many if not all of these technologies will include AI components.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Similarly, identifying and delivering technology solutions to increase the impact of the global organization. &lt;/strong&gt;This could include improvements to our&lt;strong&gt; &lt;/strong&gt;learning portals for network staff, fellows and alumni, an online platform enabling teachers and teacher coaches across and beyond our network to engage in our global professional development learning community, or a new global “constituent voice” system that enables all our network partners to surface feedback from key constituents in ways that strengthen global learning loops.&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Taking an AI-forward approach &lt;/strong&gt;to increase organizational effectiveness, increase our impact in supporting network partners in their work, and evolve our systems and ways of working to incorporate new tools and technologies.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Successful management of two solutions engineers and a UI/UX specialist&lt;/strong&gt; to deliver your ambitious strategy and goals.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;Key Responsibilities :&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;Strategy Development&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Working across network partners and internal stakeholders including our AI and Ed Tech Initiative team to build context and identify key potential technology solutions to accelerate impact&lt;/li&gt;
&lt;li&gt;Developing a responsive and evolving strategy to prioritize and develop these key technologies, working closely with the Technology &amp;amp; Innovation team and key senior stakeholders to invest them in the strategy&lt;/li&gt;
&lt;li&gt;Providing regular updates internally and externally regarding progress, and regularly revisiting and modifying the solutions strategy as needs change&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements Gathering, Analysis and Execution&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Gathering requirements for prioritized projects through stakeholder interviews and discussion, ensuring that all projects are accessible, inclusive of the various needs of the network and sustainable for all network partners&lt;/li&gt;
&lt;li&gt;Synthesizing requirements and developing holistic solutions to meet the needs of your stakeholders, ensuring that key needs and requirements are met within project and budgetary constraints&lt;/li&gt;
&lt;li&gt;Working both individually and collaboratively across the Technology &amp;amp; Innovation team and any external vendors or collaborators needed to develop and deliver prioritized solutions&lt;/li&gt;
&lt;li&gt;Ensuring that end users are trained and supported along with the Technology &amp;amp; Innovation Operations team&lt;/li&gt;
&lt;li&gt;Identifying key metrics and measures of success, and reporting on those throughout the phases of each project&lt;/li&gt;
&lt;li&gt;Identifying and managing key improvements through user and stakeholder interviews&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Team Management&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead a team of 2 within the broader Technology &amp;amp; Innovation team to deliver on&amp;nbsp; your solutions strategy for the organization and broader network&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Community Building and Management&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Supplementing the work of the AI and Ed Tech Initiative team, helping develop a community of technology enthusiasts across the network, and working across key stakeholders internally and throughout the network to share best practice and amplify the impact of community members&lt;/li&gt;
&lt;li&gt;Where possible, involving the community members in the development of the technology solutions identified as part of the three year strategy&lt;/li&gt;
&lt;li&gt;Encouraging and supporting community-developed solutions&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;Qualifications&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Computer Science or related degree and/or equivalent years of formal training and experience, with a clear track record of delivering AI-forward solutions in a broad range of contexts&amp;nbsp;&lt;/li&gt;
&lt;li&gt;7+ years of relevant working experience, including designing and delivering AI-powered solutions, with a proven portfolio showcasing high-impact, scalable implementations across diverse contexts&lt;/li&gt;
&lt;li&gt;Strong experience with AI libraries and frameworks, as well as associated Typescript and Python skills&lt;/li&gt;
&lt;li&gt;REST-based API integration experience, preferably including experience with popular Generative AI APIs and libraries&lt;/li&gt;
&lt;li&gt;Proficiency in Git and other version control systems is essential, with a proven ability to effectively manage code repositories, track changes, and collaborate with team members using branching, merging, and pull request workflows.&lt;/li&gt;
&lt;li&gt;Ability to design easy to use and compelling user interfaces and experiences&lt;/li&gt;
&lt;li&gt;Experience with Cloud Technologies, including Google Cloud&lt;/li&gt;
&lt;li&gt;Comfort and experience in engaging with new technologies&lt;/li&gt;
&lt;li&gt;Participation in open-source development projects and communities&lt;/li&gt;
&lt;li&gt;An understanding of working with technology in bandwidth-constrained environments&lt;/li&gt;
&lt;li&gt;Passion about Education, AI and Ed Tech&lt;/li&gt;
&lt;li&gt;History of driving technology projects from inception to delivery&lt;/li&gt;
&lt;li&gt;Strong business analyst skills, communications skills and ability to manage multiple diverse stakeholders&lt;/li&gt;
&lt;li&gt;Sensitivity to diversity in backgrounds and beliefs (e.g., racial, cultural, socioeconomic, political, etc.)&lt;/li&gt;
&lt;li&gt;Deeply committed to the mission, vision and values of Teach For All&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;Additional desirable skills/experiences&amp;nbsp;&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Comfort and curiosity in engaging with new and emerging technologies&lt;/li&gt;
&lt;li&gt;Participation in open-source development projects and communities&lt;/li&gt;
&lt;li&gt;Experience working in bandwidth-constrained environments&lt;/li&gt;
&lt;li&gt;Passion for Education, AI and EdTech&lt;/li&gt;
&lt;li&gt;Proven track record of driving technology projects from inception to delivery&lt;/li&gt;
&lt;li&gt;Sensitivity to diversity in backgrounds and beliefs (e.g., racial, cultural, socioeconomic, political, etc.)&lt;/li&gt;
&lt;li&gt;Strong alignment with and commitment to the mission, vision, and values of Teach For All&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What Teach For All Offers:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://teachforall.org/diversity&quot;&gt;Commitment&lt;/a&gt; to cultivating a culture in which all staff members feel they belong, are valued for their contributions, and have an impact on our organization’s progress&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Professional and personal development experiences and ample opportunities to make a positive impact on the work of Teach For All and beyond&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Comprehensive benefits package designed for your well-being and work-life needs&lt;/li&gt;
&lt;li&gt;All roles are 100% remote; in some locations we offer the option for in-office collaborations&lt;/li&gt;
&lt;li&gt;Generous time off and flexible work arrangements&lt;/li&gt;
&lt;li&gt;And much more!&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This role is a three-year fixed term contract. Salary for this position is competitive and dependent on country of hire and prior work experience and includes a comprehensive benefits package.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Work Authorization&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This position&lt;strong&gt; does not offer&lt;/strong&gt; employment visa sponsorship, immigration assistance, or support for work permits or residency applications. To be considered, candidates must already possess valid &lt;strong&gt;work and residency authorization&lt;/strong&gt; to work in the country of hire at the time of application.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Travel and Hours&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Travel up to 20% is possible when it is safe to do so and in accordance with local travel guidelines. Given that we work across different time zones, some non-traditional hours for early or later calls are an expectation of this role. This role will communicate and work globally regardless of location.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Apply now&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;If this opportunity sounds like the next best step in your career, please submit your resume or curriculum vitae (CV) and a one-page letter of motivation (in English) directly online. Your letter should summarize motivations for your application and how your skills and experience align with the terms of this opportunity. We look forward to learning about you and your passion for ensuring educational opportunity for all&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Teach For All&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Teach For All is a global network of over 60 independent, locally led organizations and a global organization united by a commitment to developing collective leadership to ensure all children can fulfill their potential. Each network partner recruits and develops promising leaders to teach in their nations’ under-resourced schools and communities and, with this foundation, to work with others, inside and outside of education, towards a world where all children have the education, support, and opportunity to shape a better future. Teach For All’s global organization works to increase the network’s impact by supporting the development of new organizations; fostering network connectivity and learning; providing coaching and consulting; and enabling access to global resources for the benefit of the network.&lt;/p&gt;

lsvp-fireworks-ai:greenhouse:4256942009.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h2&gt;&lt;strong&gt;About Us:&lt;/strong&gt;&lt;/h2&gt;
&lt;p data-start=&quot;107&quot; data-end=&quot;729&quot;&gt;At Fireworks, we’re building the future of generative AI infrastructure. Our platform delivers the highest-quality models with the fastest and most scalable inference in the industry. We’ve been independently benchmarked as the leader in LLM inference speed and are driving cutting-edge innovation through projects like our own function calling and multimodal models. Fireworks is a Series C company valued at $4 billion and backed by top investors including Benchmark, Sequoia, Lightspeed, Index, and Evantic. We’re an ambitious, collaborative team of builders, founded by veterans of Meta PyTorch and Google Vertex AI.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;About The Role:&lt;/h3&gt;
&lt;p&gt;This is a new role within the Fireworks AI Marketing team, key to driving our pipeline efforts within events and creating a program for startup founders and early-stage operators. You’ll own the community, content, and marketing programs needed to build a vibrant, active, and engaged founder/operator network—one that shares startup journeys and best practices, provides product feedback internally, and champions Fireworks as an essential tool for early-stage teams. If you&#39;re a passionate field and experiential marketer looking for an opportunity to create extraordinary in-person experiences and build from the ground up, this is your chance to create innovative programs that directly shape Fireworks AI&#39;s brand experience in SF.&lt;/p&gt;
&lt;p&gt;You&#39;ll collaborate closely with cross-functional stakeholders in sales and customer success, delivering events that bolster the AMER sales team. You&#39;ll partner with our product marketing, creative studio, partner, devrel, and demand generation teams to develop high-value events. These in-person experiences will provide top-notch content and experiences for our customers and prospects.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;Key Responsibilities:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Create top notch experiences to delight customers and prospects, with a guest-first approach to creating field events and experiences that bring our brand and product to life.&lt;/li&gt;
&lt;li&gt;Own end-to-end planning, execution, vendors, budgets, timelines of all event and field programs, including executive dinners, roundtables. workshops, trade-shows, and co-sponsored partner activations.&lt;/li&gt;
&lt;li&gt;Drive measurable pipeline and revenue impact from every program&lt;/li&gt;
&lt;li&gt;Develop pre-event, day-of, and post-event engagement strategies that maximize registration-to-attendance conversion and sales follow-up&lt;/li&gt;
&lt;li&gt;Work hand-in-hand with sales teams to build targeted invite lists and ensure strong attendance from priority accounts&lt;/li&gt;
&lt;li&gt;Track and report on program ROI to make recommendations on how we invest in field events to drive incremental business impact.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Skills You&#39;ll Need to Bring:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;5 + years of field marketing or event marketing experience in B2B SaaS&lt;/li&gt;
&lt;li&gt;A passion for all things field and experiential marketing. You understand the purpose and place for all types of events - executive events, tradeshows, networking events - taking pride in delivering on the finest of details that make the difference between a good event and a &lt;em&gt;great&lt;/em&gt; event.&lt;/li&gt;
&lt;li&gt;Are a strong cross-functional collaborator who can work effectively with Sales, Partnerships, Creative, Communications, and executive stakeholders&lt;/li&gt;
&lt;li&gt;Experience working cross functionally with sales leadership, sales representatives, customer success, creative, content, and product marketing.&lt;/li&gt;
&lt;li&gt;Proficient in CRM and marketing automation software, must is Salesforce&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Nice to Haves:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience at a startup or hyper-growth company is preferred; especially within the Bay Area&lt;/li&gt;
&lt;li&gt;Experience in startup marketing (B2B startup / founder-led GTM) is a plus&lt;/li&gt;
&lt;li&gt;Experience delivering both in-person field events &amp;amp; larger scale user conferences&lt;/li&gt;
&lt;li&gt;Familiarity with the AI/ML landscape and how developer and enterprise teams are adopting AI solutions.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;Total compensation for this role also includes meaningful equity in a fast-growing startup, along with a competitive salary and comprehensive benefits package. Base salary is determined by a range of factors including individual qualifications, experience, skills, interview performance, market data, and work location. The listed salary range is intended as a guideline and may be adjusted.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Base Pay Range (Plus Equity)&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$210,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$230,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h2&gt;&lt;strong&gt;Why Fireworks AI?&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Solve Hard Problems: Tackle challenges at the forefront of AI infrastructure, from low-latency inference to scalable model serving.&lt;/li&gt;
&lt;li&gt;Build What’s Next: Work with bleeding-edge technology that impacts how businesses and developers harness AI globally.&lt;/li&gt;
&lt;li&gt;Ownership &amp;amp; Impact: Join a fast-growing, passionate team where your work directly shapes the future of AI—no bureaucracy, just results.&lt;/li&gt;
&lt;li&gt;Learn from the Best: Collaborate with world-class engineers and AI researchers who thrive on curiosity and innovation.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;Fireworks AI is an equal-opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all innovators.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

mbaexchange-adasia:greenhouse:7408293.descriptionHtml:
&lt;p&gt;AnyMind Groupは創業9年目、アジア15か国・25拠点で事業を展開する急成長テックカンパニーです。「誰もがビジネスに熱狂する世界を創る」というビジョンのもと、マーケティング、EC、D2C、DX・AI・データ領域まで幅広い事業を横断し、“ブランド・ビジネスの成長”を総合的に支援するプロダクトとサービスを提供しています。日本法人であるAnyMind Japanにおいても多岐にわたるソリューションを統合的に提供し、企業の課題を横断的に解決する事業・組織づくりを加速しています。&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;業務内容&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;本ポジションは、AnyMindが展開する全事業・全プロダクトを横断し、課題整理 → 戦略設計 → 提案 → 条件交渉 → 受注 → 事業部連携まで一気通貫で推進するフィールドセールスのマネージャー候補です。&lt;br&gt;ISが創出した商談やインバウンドを起点に、事業横断の最適解を組み立てるコンサルティング型営業として活躍いただきます。&lt;/p&gt;
&lt;p&gt;対象ソリューションは以下すべて：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;広告・デジタル／SNSマーケティング&lt;/li&gt;
&lt;li&gt;インフルエンサーマーケティング&lt;/li&gt;
&lt;li&gt;EC／D2C／ライブコマース&lt;/li&gt;
&lt;li&gt;越境EC（中国・ASEAN・中東・US）&lt;/li&gt;
&lt;li&gt;インバウンドプロモーション&lt;/li&gt;
&lt;li&gt;AI／データ活用／DXコンサルティング&lt;/li&gt;
&lt;li&gt;クリエイティブ&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;■業務内容&lt;/h2&gt;
&lt;p&gt;① 課題・要件整理〜案件スコープ定義&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;経営／事業課題のヒアリング&lt;/li&gt;
&lt;li&gt;マーケ／EC／越境／DXなど複数領域を組み合わせた最適解の設計&lt;/li&gt;
&lt;li&gt;中長期戦略に基づく企画・スコープ定義&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;② 提案・商談推進・クロージング&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;IS／マーケとの連携による商談推進&lt;/li&gt;
&lt;li&gt;複数ソリューションを統合した提案ストーリーの構築&lt;/li&gt;
&lt;li&gt;事業部責任者との協議によるプラン精緻化&lt;/li&gt;
&lt;li&gt;クロージング／契約条件交渉／受注リード&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;③ 事業部連携による案件推進&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;受注後のプロジェクト定義〜キックオフ参画&lt;/li&gt;
&lt;li&gt;要件整理・社内外調整&lt;/li&gt;
&lt;li&gt;プロジェクト成功に向けた進行管理&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;④ 横断型営業組織の仕組み化&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;横断型営業モデル（役割分担／情報連携）の最適化&lt;/li&gt;
&lt;li&gt;IS／マーケ／事業部と連動した商談プロセス構築&lt;/li&gt;
&lt;li&gt;プレイブック・ナレッジ整備&lt;/li&gt;
&lt;li&gt;営業DX／データ可視化プロジェクトへの参画&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;必須要件&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;BtoB営業（またはコンサル/ソリューション提案）経験 3年以上&lt;/li&gt;
&lt;li&gt;複数ステークホルダーを巻き込む商談推進スキル&lt;/li&gt;
&lt;li&gt;マルチプロダクト/複数事業領域を扱った経験（または志向）&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;歓迎要件&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;コンサルティングファーム/広告代理店/EC/DX/マーケ領域の提案経験&lt;/li&gt;
&lt;li&gt;大手企業向けのアカウント営業経験&lt;/li&gt;
&lt;li&gt;クロスファンクションプロジェクトの推進経験&lt;/li&gt;
&lt;li&gt;英語/中国語/ASEAN圏でのビジネス経験&lt;/li&gt;
&lt;li&gt;スタートアップ/マルチ事業会社での経験&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;福利厚生&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;査定（年2回）&lt;/li&gt;
&lt;li&gt;ボーナス（年1回）&lt;/li&gt;
&lt;li&gt;通勤交通費&lt;/li&gt;
&lt;li&gt;完全週休二日（土日祝）、年末年始休み&lt;/li&gt;
&lt;li&gt;有給休日&lt;/li&gt;
&lt;li&gt;慶弔休暇、産休、育休&lt;/li&gt;
&lt;li&gt;社会保険：労災保険、雇用保険、健康保険、厚生年金完備&lt;/li&gt;
&lt;li&gt;就業時間：10:00-19:00（休憩1時間を含む）&lt;/li&gt;
&lt;li&gt;オフィス：六本木ヒルズ&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;

mbaexchange-adasia:greenhouse:7496908.descriptionHtml:
&lt;h2 data-start=&quot;168&quot; data-end=&quot;628&quot;&gt;As an Influencer Marketing Executive, you’ll work closely with internal teams to plan and execute influencer campaigns, negotiate partnerships, and build strong relationships with KOLs and creators. From spotting trends to activating impactful campaigns, this role is ideal for someone who’s plugged into the creator economy, enjoys collaboration, and knows how to turn influence into results.&lt;/h2&gt;
&lt;h2&gt;&lt;strong&gt;What You&#39;ll Do&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Collaborate with cross-functional teams, including Business Development and Account Management, to understand client requirements and objectives.&lt;/li&gt;
&lt;li&gt;Conduct negotiations with influencers regarding pricing, deliverables, and contractual agreements, ensuring alignment with campaign budget constraints and client expectations.&lt;/li&gt;
&lt;li&gt;Develop innovative approaches to influencer selection, content creation, and campaign activation to maximize engagement and impact.&lt;/li&gt;
&lt;li&gt;Cultivate and maintain strong relationships with Key Opinion Leaders (KOLs) and influencers across relevant industries.&lt;/li&gt;
&lt;li&gt;Identify, onboard, and manage influencer partnerships that align with campaign goals and brand values.&lt;/li&gt;
&lt;li&gt;Stay abreast of industry trends, emerging platforms, and best practices in influencer marketing.&lt;/li&gt;
&lt;li&gt;Conduct market research and competitor analysis to identify new opportunities and potential challenges in the influencer landscape.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Who You Are&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor&#39;s degree in Marketing, Communications, Business Administration, or related field&lt;/li&gt;
&lt;li&gt;Experience in influencer marketing, with a strong portfolio of successful campaigns and partnerships would be a plus.&lt;/li&gt;
&lt;li&gt;Previous experience in client-facing roles and the ability to effectively translate client needs into actionable strategies would be a plus.&lt;/li&gt;
&lt;li&gt;Exceptional communication and interpersonal abilities, capable of building rapport with influencers, clients, and internal stakeholders.&lt;/li&gt;
&lt;li&gt;Strong analytical skills, with proficiency in data analysis and performance tracking tools.&lt;/li&gt;
&lt;li&gt;Strategic thinker with a creative mindset and a passion for staying ahead of industry trends.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Why You&#39;ll Love It&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Competitive Salary&lt;/li&gt;
&lt;li&gt;Performance Review (twice a year)&lt;/li&gt;
&lt;li&gt;Yearly Performance Bonus&lt;/li&gt;
&lt;li&gt;Annual MVP Awards&lt;/li&gt;
&lt;li&gt;Work in a professional, active, international, and dynamic environment&lt;/li&gt;
&lt;li&gt;Good chance to explore new trends in the digital market&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;

mbaexchange-anaplan:greenhouse:847434500.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;At Anaplan, we are a team of innovators focused on optimizing business decision-making through our leading AI-infused scenario planning and analysis platform so our customers can outpace their competition and the market.&lt;/p&gt;
&lt;p&gt;What unites Anaplanners across teams and geographies is our collective commitment to our customers’ success and to our Winning Culture.&lt;/p&gt;
&lt;p style=&quot;padding-left: 40px;&quot;&gt;Our customers rank among the who’s who in the Fortune 50. Coca-Cola, LinkedIn, Adobe, LVMH and Bayer are just a few of the 2,400+ global companies who rely on our best-in-class platform.&lt;/p&gt;
&lt;p style=&quot;padding-left: 40px;&quot;&gt;Our Winning Culture is the engine that drives our teams of innovators. We champion diversity of thought and ideas, we behave like leaders regardless of title, we are committed to achieving ambitious goals, and we love celebrating&lt;em&gt; &lt;/em&gt;our wins – big and small.&lt;/p&gt;
&lt;p&gt;Supported by operating principles of being strategy-led, &lt;a href=&quot;https://www.anaplan.com/careers/&quot;&gt;values&lt;/a&gt;-based and disciplined in execution, you’ll be inspired, connected, developed and rewarded here. Everything that makes you unique is welcome; join us and let’s build what’s next - together!&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Anaplan is on a mission to revolutionize business planning by connecting organizations and people to make better, faster decisions. We are seeking an expert Lead React Developer to guide our front-end engineering team in building intuitive, high-performance, and scalable user interfaces. As a technical leader, you will be responsible for the architecture, quality, and delivery of the user-facing components of our market-leading platform. You will play a critical role in shaping the user experience that empowers thousands of users to navigate complex data and make critical business decisions.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead a team of front-end developers, providing technical mentorship, guidance, and support.&lt;/li&gt;
&lt;li&gt;Architect and build robust, scalable, and maintainable front-end solutions using React and its ecosystem.&lt;/li&gt;
&lt;li&gt;Take a hands-on role in writing clean, efficient, and well-tested code, setting the standard for the team.&lt;/li&gt;
&lt;li&gt;Drive front-end technical strategy and roadmap, making key decisions on frameworks, libraries, and architecture.&lt;/li&gt;
&lt;li&gt;Lead code reviews to ensure high-quality, performance, and adherence to best practices.&lt;/li&gt;
&lt;li&gt;Work closely with product managers, UX designers, and backend engineers to translate requirements and designs into perfect user experiences.&lt;/li&gt;
&lt;li&gt;Champion best practices for front-end development, including performance optimization, accessibility, and testing.&lt;/li&gt;
&lt;li&gt;Mentor junior and mid-level developers, fostering a culture of technical excellence and continuous improvement.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Required Qualifications&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Extensive (8+ years) hands-on experience developing complex, large-scale web applications using &lt;strong&gt;React&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Deep understanding of the React ecosystem, including &lt;strong&gt;Hooks, Context API, and functional components&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Proven expertise in state management libraries such as &lt;strong&gt;Redux, Zustand, or Recoil&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Strong proficiency in &lt;strong&gt;JavaScript (ES6+) and TypeScript&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Expertise in modern front-end build tools and package managers (e.g., &lt;strong&gt;Webpack, Vite, npm, Yarn&lt;/strong&gt;).&lt;/li&gt;
&lt;li&gt;Solid experience with front-end testing frameworks like &lt;strong&gt;Jest and React Testing Library&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Experience with RESTful APIs and/or GraphQL.&lt;/li&gt;
&lt;li&gt;Demonstrated experience in a technical leadership or mentorship role.&lt;/li&gt;
&lt;li&gt;Excellent problem-solving skills and the ability to communicate complex technical concepts effectively.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Preferred Qualifications&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor&#39;s degree in computer science or a related field.&lt;/li&gt;
&lt;li&gt;Experience building and maintaining component libraries or design systems.&lt;/li&gt;
&lt;li&gt;Strong knowledge of web performance optimization techniques.&lt;/li&gt;
&lt;li&gt;Familiarity with web accessibility standards (WCAG).&lt;/li&gt;
&lt;li&gt;Experience working in a SaaS or enterprise software environment.&lt;/li&gt;
&lt;li&gt;Familiarity with CI/CD pipelines and agile development methodologies.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What Makes This Role Exciting&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As a Lead FE Developer at Anaplan, you will be at the forefront of building the user interface for a powerful and complex platform used by major global enterprises. You will have the autonomy to make significant architectural decisions and the opportunity to guide a talented team. This is a chance to solve challenging technical problems, directly influence the user experience, and see your work have a tangible impact on how businesses operate and plan for the future.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Our Commitment to Diversity, Equity, Inclusion and Belonging (DEIB) &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We believe attracting and retaining the best talent and fostering an inclusive culture strengthens our business. DEIB improves our workforce, enhances trust with our partners and customers, and drives business success. Build your career in a place where diversity, equity, inclusion and belonging aren’t just words on paper – this is what drives our innovation, it’s how we connect, and it contributes to what makes us a market leader. We believe in a hiring and working environment where all people are respected and valued, regardless of gender identity or expression, sexual orientation, religion, ethnicity, age, neurodiversity, disability status, citizenship, or any other aspect which makes people unique. We hire you for who you are, and we want you to bring your authentic self to work every day! &lt;/p&gt;
&lt;p&gt;We will ensure that individuals with disabilities are provided reasonable accommodation to participate in the job application or interview process, perform essential job functions, and receive equitable benefits and all privileges of employment. Please contact us to request accommodation. &amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Fraud Recruitment Disclaimer&lt;/strong&gt; &amp;nbsp;&lt;/p&gt;
&lt;p&gt;It has come to our attention that fraudulent and fictitious job opportunities are being circulated on the Internet. Prospective candidates are being contacted by certain individuals, mainly through telephone calls, emails and correspondence, claiming they are representatives of Anaplan. The main purpose of these correspondences and announcements is to obtain privileged information from individuals.  &lt;/p&gt;
&lt;p&gt;Anaplan does not: &amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Extend offers to candidates without an extensive interview process with a member of our recruitment team and a hiring manager via video or in person.  &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Send job offers via email. All offers are first extended verbally by a member of our internal recruitment team whenever possible and then followed up via written communication. &amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;All emails from Anaplan would come from an @anaplan.com email address. Should you have any doubts about the authenticity of an email, letter or telephone communication purportedly from, for, or on behalf of Anaplan, please send an email to people@anaplan.com before taking any further action in relation to the correspondence.  &amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;

mbaexchange-appian:greenhouse:7944012.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Here at Appian, our values of &lt;strong&gt;Intensity &lt;/strong&gt;and &lt;strong&gt;Excellence &lt;/strong&gt;define who we are. We set high standards and live up to them, ensuring that everything we do is done with care and quality. We approach every challenge with ambition and commitment, holding ourselves and each other accountable to achieve the best results. When you join Appian, you’ll be part of a passionate team dedicated to accomplishing hard things, together.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Technical Delivery Managers (TDMs) are responsible for two of our most important company objectives: (1) ensure our customers achieve remarkable business results through technology engagements and (2) drive customer growth through technology expertise, trusted advice, relationships, and, most importantly, demonstrated results.&amp;nbsp; TDMs manage and deliver innovative solutions built on the Appian platform for our customers, overseeing all aspects of agile delivery for Appian led engagements, including risk management and impediment removal. TDMs also team closely with front-line sales reps to drive growth in strategic accounts and integrated deals. TDMs engage in all aspects of driving results and growth at strategic accounts, including: project management, account management, relationship building (both customers and partners), financial management, opportunity qualification, problem identification, project/use case definition, demand generation, services positioning, and account strategy.&amp;nbsp; All of these activities are performed in partnership with Appian Sales, Appian Partners, and other members of the Customer Success team, including Customer Success Managers (CSMs).&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;To be successful in this role, you need:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience managing a book of business using financial management tools and metrics&lt;/li&gt;
&lt;li&gt;Experiencing leading agile delivery teams and managing enterprise scale technology programs , including collaborating with architects and product designers to design and deliver compelling solutions for customers&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience understanding customer’s strategic goals, positioning technology to meet their goals, developing application roadmaps with customers, and building compelling business cases to understand investments.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience with one or more value selling methods and are exceptional at creating compelling business benefits that can be used in proposals and delivery&lt;/li&gt;
&lt;li&gt;Ability to develop and maintain strategic relationships (stakeholder, buyer, influencer)&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Intellectual curiosity, bias for action, ability to thrive in ambiguity, excellent communication skills&lt;/li&gt;
&lt;li&gt;Industry-experience in one or more of the following industries: Financial Services, Pharmaceuticals, Insurance, Manufacturing (preferred)&lt;/li&gt;
&lt;li&gt;Experience with software consulting (ideally in a ERP, CRM, BPM/Workflow, Data Integration Architecture or EAI) and/or applied knowledge of enterprise architecture, including data management (Preferred)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Basic qualifications:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proven background in support State &amp;amp; Local Government contracts&lt;/li&gt;
&lt;li&gt;5+ years of experience in an agile delivery environment with at least 1 year of experience leading a team&lt;/li&gt;
&lt;li&gt;B.S./B.A. in Engineering, Computer Science, Information Systems, Mathematics or related field/degree&lt;/li&gt;
&lt;li&gt;Willingness to travel; 10% or less annually to support customer engagement&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;The base salary for this role is between $125,000.00 to $250,000.00 per year and represents a good faith and reasonable estimate of the range at the time of posting. Actual compensation will be dependent on a number of factors including, but not limited to, the candidate’s relevant work experience, qualifications, internal peer equity, and market and business conditions that exist when extending an offer. A discretionary bonus may be awarded in recognition of individual and company performance.&lt;br&gt;&lt;br&gt;In addition, Appian provides generous benefits offerings that include a 401(k) plan with company match, flexible time off, paid parental leave, medical, dental, and vision plans, life insurance, disability insurance, wellness programs, flexible spending accounts, health savings account contributions, an employee referral bonus program, and learning and development resources. Certain positions may be eligible for equity awards.&amp;nbsp;&lt;br&gt;&lt;br&gt;Pay and benefits are subject to change at any time, consistent with the terms of any applicable compensation, commission, bonus, or benefit plans.&lt;/p&gt;
&lt;p&gt;#LI-AG1&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;Tools and Resources&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;Training and Development: During onboarding, we focus on equipping new hires with the skills and knowledge for success through department-specific training. Continuous learning is a central focus at Appian, with dedicated mentorship and the First-Friend program being widely utilized resources for new hires.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;Growth Opportunities: Appian provides a diverse array of growth and development opportunities, including our leadership program tailored for new and aspiring managers, a comprehensive library of specialized department training through Appian University, skills based training, and tuition reimbursement for those aiming to advance their education. This commitment ensures that employees have access to a holistic range of development opportunities.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;Community: We’ll immerse you into our community rooted in respect starting on day one. Appian fosters inclusivity through our 8 employee-led &lt;a style=&quot;color: rgb(0, 0, 0);&quot; href=&quot;https://careers.appian.com/affinity-groups/&quot;&gt;affinity groups&lt;/a&gt;. These groups help employees build stronger internal and external networks by planning social, educational, and outreach activities to connect with Appianites and larger initiatives throughout the company.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;Benefits&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Appian offers a comprehensive benefits package designed to support your health, wellbeing, and financial future. Benefits may include health coverage, Employee Assistance Program (EAP) with free mental health support, life and disability insurance, an Employee Stock Purchase Program (ESPP), a retirement/pension plan, wellness dollars, tuition reimbursement, family-forming benefits and more. Benefits vary by country—please ask your Talent Acquisition contact for details specific to the location you are applying to.&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;About Appian&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Appian provides process automation technology. We automate complex processes in large enterprises and governments. Our platform is known for its unique reliability and scale. We’ve been automating processes for 25 years and understand enterprise operations like no one else. For more information, visit &lt;a href=&quot;http://www.appian.com/&quot;&gt;appian.com&lt;/a&gt;. [Nasdaq: APPN]&lt;/p&gt;
&lt;p&gt;Follow Appian: &lt;a href=&quot;https://www.linkedin.com/company/appian&quot;&gt;LinkedIn&lt;/a&gt;, &lt;a href=&quot;https://www.youtube.com/@appian&quot;&gt;Youtube&lt;/a&gt;, &lt;a href=&quot;https://www.instagram.com/appiancorp/&quot;&gt;Instagram&lt;/a&gt;, &lt;a href=&quot;https://www.facebook.com/AppianCorporation/&quot;&gt;Facebook&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Appian is an equal opportunity employer that strives to attract and retain the best talent. All qualified applicants will receive consideration for employment without regard to any characteristic protected by applicable federal, state, or local law.&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Appian provides reasonable accommodations to applicants in accordance with all applicable laws. If you need a reasonable accommodation for any part of the employment process, please contact us by email at&amp;nbsp;&lt;a href=&quot;mailto:ReasonableAccommodations@appian.com&quot; target=&quot;_blank&quot;&gt;ReasonableAccommodations@appian.com&lt;/a&gt;. Please note that only inquiries concerning a request for reasonable accommodation will be responded to from this email address.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;a href=&quot;https://careers.appian.com/applicant-and-candidate-privacy-notice/&quot;&gt;Appian&#39;s Applicant &amp;amp; Candidate Privacy Notice&lt;/a&gt;&amp;nbsp;&amp;nbsp;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

